import numpy as np


def rank1_accuracy(scores, true_idx):
    s = np.asarray(scores, dtype=float)
    if s.shape[0] == 0:
        return 0.0
    predicted = np.argmax(s, axis=1)
    return float(np.mean(predicted == np.asarray(true_idx)))
